import React from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { Thermometer, Gauge, Droplets, Power, AlertCircle, Check } from 'lucide-react';
import { SYSTEM_CONSTANTS } from '../utils/constants';

const ProcessMonitor = ({ processState, processHistory, isRunning }) => {
  const getStatusColor = (value, min, max) => {
    const range = max - min;
    const warning = max - range * 0.15;
    const critical = max - range * 0.05;

    if (value >= critical) return '#ef4444';
    if (value >= warning) return '#f59e0b';
    return '#10b981';
  };

  const getChartData = () => {
    if (!processHistory.temperature) return [];

    const length = processHistory.temperature.length;
    return Array.from({ length }, (_, i) => ({
      index: i,
      temperature: processHistory.temperature[i]?.toFixed(1),
      pressure: processHistory.pressure[i]?.toFixed(1),
      flowRate: processHistory.flowRate[i]?.toFixed(1)
    }));
  };

  const chartData = getChartData();

  return (
    <div className="panel process-monitor">
      <div className="panel-header">
        <h2>
          <Gauge size={20} />
          Industrial Process Monitor
        </h2>
        <span className={`monitor-status ${isRunning ? 'active' : 'inactive'}`}>
          {isRunning ? 'ACTIVE' : 'STANDBY'}
        </span>
      </div>

      <div className="process-indicators">
        <div className="indicator-card">
          <div className="indicator-header">
            <Thermometer size={24} />
            <span>Temperature</span>
          </div>
          <div className="indicator-value" style={{ 
            color: getStatusColor(
              processState.temperature, 
              SYSTEM_CONSTANTS.SAFETY_LIMITS.TEMPERATURE_MIN,
              SYSTEM_CONSTANTS.SAFETY_LIMITS.TEMPERATURE_MAX
            )
          }}>
            {processState.temperature?.toFixed(1) || '0.0'}°C
          </div>
          <div className="indicator-limits">
            <span>Min: {SYSTEM_CONSTANTS.SAFETY_LIMITS.TEMPERATURE_MIN}°C</span>
            <span>Max: {SYSTEM_CONSTANTS.SAFETY_LIMITS.TEMPERATURE_MAX}°C</span>
          </div>
          <div className="indicator-bar">
            <div 
              className="indicator-bar-fill"
              style={{ 
                width: `${(processState.temperature / SYSTEM_CONSTANTS.SAFETY_LIMITS.TEMPERATURE_MAX) * 100}%`,
                background: getStatusColor(
                  processState.temperature,
                  SYSTEM_CONSTANTS.SAFETY_LIMITS.TEMPERATURE_MIN,
                  SYSTEM_CONSTANTS.SAFETY_LIMITS.TEMPERATURE_MAX
                )
              }}
            />
          </div>
        </div>

        <div className="indicator-card">
          <div className="indicator-header">
            <Gauge size={24} />
            <span>Pressure</span>
          </div>
          <div className="indicator-value" style={{ 
            color: getStatusColor(
              processState.pressure,
              SYSTEM_CONSTANTS.SAFETY_LIMITS.PRESSURE_MIN,
              SYSTEM_CONSTANTS.SAFETY_LIMITS.PRESSURE_MAX
            )
          }}>
            {processState.pressure?.toFixed(1) || '0.0'} PSI
          </div>
          <div className="indicator-limits">
            <span>Min: {SYSTEM_CONSTANTS.SAFETY_LIMITS.PRESSURE_MIN} PSI</span>
            <span>Max: {SYSTEM_CONSTANTS.SAFETY_LIMITS.PRESSURE_MAX} PSI</span>
          </div>
          <div className="indicator-bar">
            <div 
              className="indicator-bar-fill"
              style={{ 
                width: `${(processState.pressure / SYSTEM_CONSTANTS.SAFETY_LIMITS.PRESSURE_MAX) * 100}%`,
                background: getStatusColor(
                  processState.pressure,
                  SYSTEM_CONSTANTS.SAFETY_LIMITS.PRESSURE_MIN,
                  SYSTEM_CONSTANTS.SAFETY_LIMITS.PRESSURE_MAX
                )
              }}
            />
          </div>
        </div>

        <div className="indicator-card">
          <div className="indicator-header">
            <Droplets size={24} />
            <span>Flow Rate</span>
          </div>
          <div className="indicator-value" style={{ 
            color: getStatusColor(
              processState.flowRate,
              SYSTEM_CONSTANTS.SAFETY_LIMITS.FLOW_RATE_MIN,
              SYSTEM_CONSTANTS.SAFETY_LIMITS.FLOW_RATE_MAX
            )
          }}>
            {processState.flowRate?.toFixed(1) || '0.0'} L/min
          </div>
          <div className="indicator-limits">
            <span>Min: {SYSTEM_CONSTANTS.SAFETY_LIMITS.FLOW_RATE_MIN} L/min</span>
            <span>Max: {SYSTEM_CONSTANTS.SAFETY_LIMITS.FLOW_RATE_MAX} L/min</span>
          </div>
          <div className="indicator-bar">
            <div 
              className="indicator-bar-fill"
              style={{ 
                width: `${(processState.flowRate / SYSTEM_CONSTANTS.SAFETY_LIMITS.FLOW_RATE_MAX) * 100}%`,
                background: getStatusColor(
                  processState.flowRate,
                  SYSTEM_CONSTANTS.SAFETY_LIMITS.FLOW_RATE_MIN,
                  SYSTEM_CONSTANTS.SAFETY_LIMITS.FLOW_RATE_MAX
                )
              }}
            />
          </div>
        </div>
      </div>

      <div className="process-status">
        <div className="status-item">
          <Power size={20} />
          <span>Pump Status:</span>
          <strong style={{ color: processState.pumpStatus ? '#10b981' : '#ef4444' }}>
            {processState.pumpStatus ? 'ON' : 'OFF'}
          </strong>
        </div>

        <div className="status-item">
          <Gauge size={20} />
          <span>Valve Position:</span>
          <strong>{processState.valvePosition || 0}%</strong>
        </div>

        <div className="status-item">
          {processState.safetyInterlock ? <Check size={20} /> : <AlertCircle size={20} />}
          <span>Safety Interlock:</span>
          <strong style={{ color: processState.safetyInterlock ? '#10b981' : '#ef4444' }}>
            {processState.safetyInterlock ? 'ACTIVE' : 'TRIPPED'}
          </strong>
        </div>

        <div className="status-item">
          {processState.alarmActive ? <AlertCircle size={20} /> : <Check size={20} />}
          <span>System Alarms:</span>
          <strong style={{ color: processState.alarmActive ? '#ef4444' : '#10b981' }}>
            {processState.alarmActive ? 'ACTIVE' : 'CLEAR'}
          </strong>
        </div>
      </div>

      {chartData.length > 0 && (
        <div className="process-chart">
          <h3>Process Trends</h3>
          <ResponsiveContainer width="100%" height={250}>
            <LineChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
              <XAxis 
                dataKey="index" 
                stroke="#9ca3af"
                label={{ value: 'Time', position: 'insideBottom', offset: -5 }}
              />
              <YAxis stroke="#9ca3af" />
              <Tooltip 
                contentStyle={{ 
                  backgroundColor: '#1f2937', 
                  border: '1px solid #374151',
                  borderRadius: '4px'
                }}
              />
              <Legend />
              <Line 
                type="monotone" 
                dataKey="temperature" 
                stroke="#ef4444" 
                strokeWidth={2}
                dot={false}
                name="Temperature (°C)"
              />
              <Line 
                type="monotone" 
                dataKey="pressure" 
                stroke="#3b82f6" 
                strokeWidth={2}
                dot={false}
                name="Pressure (PSI)"
              />
              <Line 
                type="monotone" 
                dataKey="flowRate" 
                stroke="#10b981" 
                strokeWidth={2}
                dot={false}
                name="Flow Rate (L/min)"
              />
            </LineChart>
          </ResponsiveContainer>
        </div>
      )}
    </div>
  );
};

export default ProcessMonitor;
